import sys
input = lambda : sys.stdin.readline().rstrip('\n\r')
sys.setrecursionlimit(10 ** 6)
from collections import Counter, defaultdict, deque
from itertools import accumulate, chain, zip_longest, product, repeat
from bisect import bisect_left, bisect_right
from math import gcd
from string import ascii_lowercase
from functools import cmp_to_key
mod = 10 ** 9 + 7
mod_2 = 998244353

def node_cost(tree, root):
	if root << 1 >= len(tree):
		return (0, tree[root])
	(cx, sx) = node_cost(tree, root << 1)
	(cy, sy) = node_cost(tree, root << 1 | 1)
	if sx != sy:
		if sx < sy:
			return (cx + cy + 1, tree[root] + sx + sy)
		else:
			return (cx + cy + 1, tree[root] + sy + sx)
	else:
		return (cx + cy, tree[root] + sx + sy)

def solve():
	n = int(input())
	tree = ['$'] + list(input())
	(ans, _) = node_cost(tree, 1)
	return pow(2, ans, mod_2)
val = solve()
print(val)
